      }
    } catch (e, stackTrace) {
      debugPrint('TorboxDownloadsScreen: Error during ZIP download: $e');
      debugPrint('Stack trace: $stackTrace');
      if (mounted) {
        messenger.showSnackBar(
          SnackBar(
            content: Text(
